export interface NotebookStreamOutput {
  type: "stream"
  name: "stdout" | "stderr"
  /** Raw text. ANSI colors and carriage returns (progress bars) are honored. */
  text: string
}

export interface NotebookTextOutput {
  /** An `execute_result` or `display_data` with only `text/plain`. */
  type: "text"
  text: string
}

export interface NotebookTableColumn {
  name: string
  /** Numbers align to the end by default, everything else to the start. */
  align?: "start" | "end"
}

/** One table cell. `null` shows a NULL badge, `NaN` a NaN badge. */
export type NotebookCellValue = string | number | boolean | null | undefined

export interface NotebookTableOutput {
  /** A DataFrame, the way pandas prints one: index column, typed cells, size footer. */
  type: "table"
  columns: Array<string | NotebookTableColumn>
  rows: NotebookCellValue[][]
  /** Index labels. Defaults to 0, 1, 2 and so on. `false` hides the index. */
  index?: Array<string | number> | false
  /** Header above the index column, for example `plan`. */
  indexName?: string
  /** Full size of the frame when `rows` is a sample. Shows the "611 rows x 6 columns" footer. */
  totalRows?: number
  totalColumns?: number
  /**
   * `rows` holds a head and a tail: the first `headRows` rows, then the last ones. A quiet
   * ellipsis row marks the gap, like pandas.
   */
  headRows?: number
}

export interface NotebookImageOutput {
  /** `image/png`, `image/svg+xml` or any image URL. Width and height reserve the space. */
  type: "image"
  src: string
  alt: string
  width: number
  height: number
}

export interface NotebookErrorOutput {
  type: "error"
  /** Exception name, for example `KeyError`. */
  ename: string
  evalue: string
  /** Traceback lines as the kernel sends them, ANSI escapes included. */
  traceback?: string[]
}

export type NotebookOutput =
  | NotebookStreamOutput
  | NotebookTextOutput
  | NotebookTableOutput
  | NotebookImageOutput
  | NotebookErrorOutput

const OutputContext = React.createContext<{ maxHeight: number | string; running: boolean }>({
  maxHeight: 320,
  running: false,
})

/**
 * One output's own scroll area, capped at `maxOutputHeight`. While the cell runs it follows the
 * newest line until the reader scrolls up, and follows again once they return to the bottom.
 */
function OutputScroll({
  label,
  className,
  children,
}: {
  label: string
  className?: string
  children: React.ReactNode
}) {
  const { maxHeight, running } = React.useContext(OutputContext)
  const ref = React.useRef<HTMLElement>(null)
  const stuck = React.useRef(true)
  React.useLayoutEffect(() => {
    const el = ref.current
    if (el && running && stuck.current) el.scrollTop = el.scrollHeight
  })
  return (
    <section
      ref={ref}
      aria-label={label}
      // biome-ignore lint/a11y/noNoninteractiveTabindex: scrollable regions must be reachable by keyboard
      tabIndex={0}
      onScroll={(event) => {
        const el = event.currentTarget
        stuck.current = el.scrollHeight - el.scrollTop - el.clientHeight < 8
      }}
      style={{ maxHeight }}
      className={cn(
        "chatcn-scroll relative overflow-auto overscroll-contain outline-none [overflow-anchor:none]",
        "focus-visible:outline-(color:--chatcn-accent) focus-visible:outline-2 focus-visible:outline-offset-2",
        className,
      )}
    >
      {children}
    </section>
  )
}

/**
 * ANSI terminal output to theme-aware styled spans.
 *
 * Parses SGR (bold, dim, italic, underline, inverse, reset, 8 and 16 colors, 256 colors and
 * truecolor) and maps every color onto the kit palette: six hues (red, green, amber, blue,
 * purple, teal) tuned for contrast in light and dark, plus four gray tones. Grays and low
 * saturation colors go by lightness, so a tool's own palette never fights the theme. Cursor movement and other control sequences are stripped. OSC 8
 * hyperlinks keep their text and become links. A carriage return rewinds the line, so progress
 * bars that redraw themselves collapse to their latest frame.
 *
 * The parser is incremental: `push(chunk)` only reads the new text, finished lines are frozen
 * objects that never change, and only the last line is rebuilt. Streaming output stays cheap.
 */

/** The kit hues ANSI colors map onto. */
type AnsiHue = "red" | "green" | "amber" | "blue" | "purple" | "teal"

/** Four gray tones plus the kit hues. */
type AnsiTone = "strong" | "default" | "muted" | "subtle" | AnsiHue

interface AnsiStyle {
  bold?: boolean
  dim?: boolean
  italic?: boolean
  underline?: boolean
  inverse?: boolean
  strike?: boolean
  /** Foreground tone. Undefined means the default text color. */
  tone?: AnsiTone
  /** A colored background becomes that hue's tint; a gray one becomes a subtle fill. */
  background?: "fill" | AnsiHue
  /** OSC 8 hyperlink target. */
  href?: string
}

interface AnsiSpan {
  text: string
  style: AnsiStyle
}

/** A line of output. Finished lines are frozen and keep their identity across pushes. */
type AnsiLine = readonly AnsiSpan[]

function sameStyle(a: AnsiStyle, b: AnsiStyle) {
  return (
    a.bold === b.bold &&
    a.dim === b.dim &&
    a.italic === b.italic &&
    a.underline === b.underline &&
    a.inverse === b.inverse &&
    a.strike === b.strike &&
    a.tone === b.tone &&
    a.background === b.background &&
    a.href === b.href
  )
}

const ESC = "\u001b"

/** Tones for the 16 basic colors (0 to 7 normal, 8 to 15 bright). */
const BASIC: AnsiTone[] = [
  "subtle", // black: unreadable on dark canvases, so it reads as secondary text
  "red",
  "green",
  "amber", // yellow: pure yellow fails contrast on white, amber reads in both themes
  "blue",
  "purple", // magenta
  "teal", // cyan
  "default", // white
  "subtle", // bright black (gray): the usual "dim" color
  "red",
  "green",
  "amber",
  "blue",
  "purple",
  "teal",
  "strong",
]

const HUES = new Set<AnsiTone>(["red", "green", "amber", "blue", "purple", "teal"])

const asBackground = (tone: AnsiTone | undefined): AnsiStyle["background"] =>
  tone && HUES.has(tone) ? (tone as AnsiHue) : "fill"

function rgbFor256(n: number): [number, number, number] {
  if (n >= 232) {
    const v = 8 + (n - 232) * 10
    return [v, v, v]
  }
  const i = n - 16
  const steps = [0, 95, 135, 175, 215, 255]
  return [steps[Math.floor(i / 36)] ?? 0, steps[Math.floor(i / 6) % 6] ?? 0, steps[i % 6] ?? 0]
}

/** Hue angle (degrees) to the nearest kit hue. */
function hueFor(angle: number): AnsiHue {
  if (angle < 20 || angle >= 330) return "red"
  if (angle < 70) return "amber"
  if (angle < 160) return "green"
  if (angle < 200) return "teal"
  if (angle < 260) return "blue"
  return "purple"
}

/** Maps an RGB color to a tone: saturated colors take the nearest kit hue, grays go by lightness. */
function toneForRgb(r: number, g: number, b: number): AnsiTone {
  const max = Math.max(r, g, b)
  const min = Math.min(r, g, b)
  const chroma = max - min
  if (chroma > 60 && max > 80) {
    let h: number
    if (max === r) h = ((g - b) / chroma) % 6
    else if (max === g) h = (b - r) / chroma + 2
    else h = (r - g) / chroma + 4
    return hueFor((h * 60 + 360) % 360)
  }
  const l = 0.2126 * r + 0.7152 * g + 0.0722 * b
  if (l < 70) return "subtle"
  if (l < 150) return "muted"
  if (l < 225) return "default"
  return "strong"
}

function toneFor256(n: number): AnsiTone {
  if (n < 16) return BASIC[n] ?? "default"
  const [r, g, b] = rgbFor256(n)
  return toneForRgb(r, g, b)
}

/** Reads an extended color (38;5;n or 38;2;r;g;b) starting at `i`. Returns the tone and new index. */
function readExtended(codes: number[], i: number): [AnsiTone | undefined, number] {
  const mode = codes[i + 1]
  if (mode === 5) return [toneFor256(codes[i + 2] ?? 0), i + 2]
  if (mode === 2) {
    return [toneForRgb(codes[i + 2] ?? 0, codes[i + 3] ?? 0, codes[i + 4] ?? 0), i + 4]
  }
  return [undefined, i]
}

/** Applies one SGR parameter list to a style. Returns a new style object. */
function applySgr(style: AnsiStyle, params: string): AnsiStyle {
  const codes = params === "" ? [0] : params.split(/[;:]/).map((p) => (p === "" ? 0 : Number(p)))
  let next: AnsiStyle = { ...style }
  for (let i = 0; i < codes.length; i++) {
    const c = codes[i] ?? 0
    if (c === 0) next = next.href ? { href: next.href } : {}
    else if (c === 1) next.bold = true
    else if (c === 2) next.dim = true
    else if (c === 3) next.italic = true
    else if (c === 4) next.underline = true
    else if (c === 7) next.inverse = true
    else if (c === 9) next.strike = true
    else if (c === 21 || c === 22) {
      next.bold = false
      next.dim = false
    } else if (c === 23) next.italic = false
    else if (c === 24) next.underline = false
    else if (c === 27) next.inverse = false
    else if (c === 29) next.strike = false
    else if (c >= 30 && c <= 37) next.tone = BASIC[c - 30]
    else if (c >= 90 && c <= 97) next.tone = BASIC[c - 90 + 8]
    else if (c === 39) next.tone = undefined
    else if (c >= 40 && c <= 47) next.background = asBackground(BASIC[c - 40])
    else if (c >= 100 && c <= 107) next.background = asBackground(BASIC[c - 100 + 8])
    else if (c === 49) next.background = undefined
    else if (c === 38) {
      const [tone, j] = readExtended(codes, i)
      next.tone = tone
      i = j
    } else if (c === 48) {
      const [tone, j] = readExtended(codes, i)
      next.background = asBackground(tone)
      i = j
    }
  }
  for (const key of Object.keys(next) as (keyof AnsiStyle)[]) {
    if (next[key] === undefined || next[key] === false) delete next[key]
  }
  return next
}

const BEL = "\u0007"

/** Incremental ANSI parser. Feed it chunks; read `lines`. */
class AnsiParser {
  /** Finished lines. Entries never change once pushed. */
  readonly done: AnsiLine[] = []
  private current: AnsiSpan[] = []
  private style: AnsiStyle = {}
  /** An escape sequence cut off at the end of the last chunk. */
  private pending = ""
  /** A carriage return was seen: the next printable character starts the line over. */
  private rewind = false

  /** Every line, the last one possibly unfinished. */
  get lines(): AnsiLine[] {
    return this.current.length > 0 ? [...this.done, this.current.slice()] : [...this.done]
  }

  /** Number of lines, counting an unfinished last line. */
  get lineCount() {
    return this.done.length + (this.current.length > 0 ? 1 : 0)
  }

  /** The last, unfinished line. Rebuilt on every push. */
  get tail(): AnsiLine {
    return this.current.slice()
  }

  reset() {
    this.done.length = 0
    this.current = []
    this.style = {}
    this.pending = ""
    this.rewind = false
  }

  private write(text: string) {
    if (!text) return
    if (this.rewind) {
      this.current = []
      this.rewind = false
    }
    const last = this.current.at(-1)
    if (last && sameStyle(last.style, this.style)) {
      this.current[this.current.length - 1] = { text: last.text + text, style: last.style }
    } else {
      this.current.push({ text, style: this.style })
    }
  }

  private newline() {
    this.done.push(Object.freeze(this.current))
    this.current = []
    this.rewind = false
  }

  private backspace() {
    const last = this.current.at(-1)
    if (!last) return
    const text = last.text.slice(0, -1)
    if (text) this.current[this.current.length - 1] = { text, style: last.style }
    else this.current.pop()
  }

  /** Feeds the next chunk of raw terminal output. */
  push(chunk: string) {
    const input = this.pending + chunk
    this.pending = ""
    let text = ""
    let i = 0
    const flush = () => {
      this.write(text)
      text = ""
    }
    while (i < input.length) {
      const ch = input[i] as string
      if (ch === ESC) {
        const next = input[i + 1]
        if (next === undefined) {
          flush()
          this.pending = input.slice(i)
          return
        }
        if (next === "[") {
          // CSI: parameters, then one final byte in @ to ~.
          let j = i + 2
          while (j < input.length && !/[@-~]/.test(input[j] as string)) j++
          if (j >= input.length) {
            flush()
            this.pending = input.slice(i)
            return
          }
          const final = input[j]
          const params = input.slice(i + 2, j)
          flush()
          if (final === "m") this.style = applySgr(this.style, params)
          else if (final === "K") {
            // Erase in line. Clearing the whole line or the rest of it both empty our model,
            // because the cursor is always at the end of `current`.
            if (params === "2" || params === "" || params === "0") this.current = []
          } else if (final === "G" && (params === "" || params === "1")) this.rewind = true
          // Everything else (cursor movement, scroll regions, modes) is dropped.
          i = j + 1
          continue
        }
        if (next === "]") {
          // OSC: ends with BEL or ESC \.
          let j = i + 2
          let end = -1
          let terminator = 0
          while (j < input.length) {
            if (input[j] === BEL) {
              end = j
              terminator = 1
              break
            }
            if (input[j] === ESC && input[j + 1] === "\\") {
              end = j
              terminator = 2
              break
            }
            j++
          }
          if (end < 0) {
            flush()
            this.pending = input.slice(i)
            return
          }
          flush()
          const body = input.slice(i + 2, end)
          if (body.startsWith("8;")) {
            const href = body.slice(body.indexOf(";", 2) + 1)
            const next = { ...this.style }
            if (href) next.href = href
            else delete next.href
            this.style = next
          }
          i = end + terminator
          continue
        }
        // Two-byte escapes (ESC 7, ESC c, ...): drop both bytes.
        i += 2
        continue
      }
      if (ch === "\n") {
        flush()
        this.newline()
      } else if (ch === "\r") {
        flush()
        if (input[i + 1] === "\n") {
          this.newline()
          i++
        } else if (i + 1 >= input.length) {
          // Could be the first half of CRLF split across chunks.
          this.pending = "\r"
        } else this.rewind = true
      } else if (ch === "\b") {
        flush()
        this.backspace()
      } else if (ch === "\t" || ch >= " ") {
        text += ch
      }
      i++
    }
    flush()
  }

  /** Plain text without escape codes, for copying. */
  toPlainText() {
    return this.lines.map((line) => line.map((s) => s.text).join("")).join("\n")
  }
}

/** Parses a whole string at once. */
function parseAnsi(input: string): AnsiLine[] {
  const parser = new AnsiParser()
  parser.push(input)
  return parser.lines
}

/* -------------------------------------------------------------------------------------------------
 * Outputs
 * -----------------------------------------------------------------------------------------------*/

const ANSI_TONE: Record<NonNullable<AnsiStyle["tone"]>, string> = {
  strong: "text-(color:--chatcn-fg) font-medium",
  default: "text-(color:--chatcn-fg)",
  muted: "text-(color:--chatcn-fg-muted)",
  subtle: "text-(color:--chatcn-fg-subtle)",
  red: "text-(color:--chatcn-red)",
  green: "text-(color:--chatcn-green)",
  amber: "text-(color:--chatcn-amber)",
  blue: "text-(color:--chatcn-blue)",
  purple: "text-(color:--chatcn-purple)",
  teal: "text-(color:--chatcn-teal)",
}

function ansiClass(style: AnsiStyle) {
  return cn(
    style.tone ? ANSI_TONE[style.tone] : undefined,
    style.dim && "opacity-75",
    style.bold && "font-semibold",
    style.italic && "italic",
    style.underline && "underline underline-offset-2",
  )
}

const AnsiRow = React.memo(function AnsiRow({ line }: { line: AnsiLine }) {
  return (
    <div className="min-h-5">
      {line.map((span, i) => {
        const className = ansiClass(span.style)
        return className ? (
          <span key={i} className={className}>
            {span.text}
          </span>
        ) : (
          <React.Fragment key={i}>{span.text}</React.Fragment>
        )
      })}
    </div>
  )
})

function AnsiText({ text, className }: { text: string; className?: string }) {
  const lines = React.useMemo(() => parseAnsi(text.replace(/\n$/, "")), [text])
  return (
    <div
      dir="ltr"
      className={cn(
        "text-[0.75rem]/[1rem] font-mono leading-5 [overflow-wrap:anywhere] whitespace-pre-wrap",
        className,
      )}
    >
      {lines.map((line, i) => (
        <AnsiRow key={i} line={line} />
      ))}
    </div>
  )
}

function StreamOutput({ output }: { output: NotebookStreamOutput }) {
  if (output.name === "stderr") {
    // Standard error is usually warnings: amber tint, never the red of a failure.
    return (
      <div
        data-slot="notebook-output"
        data-output-type="stderr"
        className="bg-(color:--chatcn-amber-bg) rounded-(--chatcn-radius-md) px-3 py-2 shadow-[inset_0_0_0_1px_var(--chatcn-amber-border)]"
      >
        <OutputScroll label="Standard error">
          <AnsiText text={output.text} className="text-(color:--chatcn-fg)" />
        </OutputScroll>
      </div>
    )
  }
  return (
    <div data-slot="notebook-output" data-output-type="stdout">
      <OutputScroll label="Standard output">
        <AnsiText text={output.text} className="text-(color:--chatcn-fg)" />
      </OutputScroll>
    </div>
  )
}

const isNumeric = (v: NotebookCellValue) => typeof v === "number"

function NullBadge({ label = "NULL" }: { label?: string }) {
  return (
    <span className="rounded-(--chatcn-radius-xs) bg-(color:--chatcn-fill) text-(color:--chatcn-fg-subtle) text-[0.75rem]/[1rem] px-1 font-mono">
      <span aria-hidden="true">{label}</span>
      <span className="sr-only">{label === "NULL" ? "null" : "not a number"}</span>
    </span>
  )
}

function formatValue(value: NotebookCellValue): React.ReactNode {
  if (value === null || value === undefined) return <NullBadge />
  if (typeof value === "number") {
    if (Number.isNaN(value)) return <NullBadge label="NaN" />
    return value.toLocaleString("en-US", { maximumFractionDigits: 6 })
  }
  if (typeof value === "boolean") return value ? "True" : "False"
  return value
}

function TableOutput({ output }: { output: NotebookTableOutput }) {
  const { maxHeight } = React.useContext(OutputContext)
  const columns = output.columns.map((c) => (typeof c === "string" ? { name: c } : c))
  const align = columns.map((col, c) => {
    if (col.align) return col.align
    const values = output.rows.map((r) => r[c]).filter((v) => v !== null && v !== undefined)
    return values.length > 0 && values.every(isNumeric) ? "end" : "start"
  })
  const showIndex = output.index !== false
  const index = output.index === false ? [] : (output.index ?? output.rows.map((_, i) => i))
  const totalRows = output.totalRows ?? output.rows.length
  const totalColumns = output.totalColumns ?? columns.length
  const truncated = totalRows > output.rows.length || totalColumns > columns.length
  const gapAt =
    output.headRows !== undefined && truncated && output.headRows < output.rows.length
      ? output.headRows
      : -1

  const th = cn(
    "text-[0.75rem]/[1rem] text-(color:--chatcn-fg-muted) bg-(color:--chatcn-bg-subtle) border-(color:--chatcn-border) sticky top-0 z-[1] h-8 border-b px-3 font-medium whitespace-nowrap",
  )
  const td = "border-(color:--chatcn-border) text-[0.8125rem]/[1.25rem] h-7 border-b px-3 whitespace-nowrap"

  return (
    <figure data-slot="notebook-output" data-output-type="table" className="flex flex-col gap-1.5">
      <section
        aria-label="Table"
        // biome-ignore lint/a11y/noNoninteractiveTabindex: scrollable regions must be reachable by keyboard
        tabIndex={0}
        style={{ maxHeight }}
        className={cn(
          "rounded-(--chatcn-radius-md) shadow-(--chatcn-shadow-border) chatcn-scroll relative max-w-full overflow-auto overscroll-contain outline-none",
          "focus-visible:outline-(color:--chatcn-accent) focus-visible:outline-2 focus-visible:outline-offset-2",
        )}
      >
        <table className="w-max min-w-full border-separate border-spacing-0 tabular-nums">
          <thead>
            <tr>
              {showIndex ? (
                <th scope="col" className={cn(th, "text-start")}>
                  {output.indexName ?? <span className="sr-only">Index</span>}
                </th>
              ) : null}
              {columns.map((col, c) => (
                <th
                  key={c}
                  scope="col"
                  className={cn(th, align[c] === "end" ? "text-end" : "text-start")}
                >
                  {col.name}
                </th>
              ))}
            </tr>
          </thead>
          <tbody className="[&_tr:last-child>*]:border-b-0">
            {output.rows.map((row, r) => (
              <React.Fragment key={r}>
                {r === gapAt ? (
                  <tr data-slot="notebook-table-gap">
                    {showIndex ? (
                      <td className={cn(td, "text-(color:--chatcn-fg-subtle)")}>
                        <span aria-hidden="true">…</span>
                        <span className="sr-only">Rows omitted</span>
                      </td>
                    ) : null}
                    {columns.map((_, c) => (
                      <td
                        key={c}
                        className={cn(
                          td,
                          "text-(color:--chatcn-fg-subtle)",
                          align[c] === "end" ? "text-end" : "text-start",
                        )}
                      >
                        <span aria-hidden="true">…</span>
                      </td>
                    ))}
                  </tr>
                ) : null}
                <tr>
                  {showIndex ? (
                    <th
                      scope="row"
                      className={cn(td, "text-(color:--chatcn-fg-muted) text-start font-medium")}
                    >
                      {index[r] ?? r}
                    </th>
                  ) : null}
                  {columns.map((_, c) => (
                    <td
                      key={c}
                      className={cn(
                        td,
                        "text-(color:--chatcn-fg) max-w-72 truncate",
                        align[c] === "end" ? "text-end" : "text-start",
                      )}
                      title={typeof row[c] === "string" ? (row[c] as string) : undefined}
                    >
                      {formatValue(row[c])}
                    </td>
                  ))}
                </tr>
              </React.Fragment>
            ))}
          </tbody>
        </table>
      </section>
      {truncated ? (
        <figcaption className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) tabular-nums">
          {totalRows.toLocaleString("en-US")} {totalRows === 1 ? "row" : "rows"} x{" "}
          {totalColumns.toLocaleString("en-US")} {totalColumns === 1 ? "column" : "columns"}
        </figcaption>
      ) : null}
    </figure>
  )
}

interface IconProps extends SVGAttributes<SVGSVGElement> {
  /** Width and height. Number means px. Default 24. */
  size?: number | string
  /** Stroke width in viewBox units (24 grid). Default 1.5. */
  strokeWidth?: number | string
  /** Keep the rendered stroke at `strokeWidth` px at any size. */
  absoluteStrokeWidth?: boolean
  /** Stroke color. Default currentColor. */
  color?: string
  /** Accessible name. Renders <title> and sets role="img"; without it the icon is aria-hidden. */
  title?: string
}

type Icon = ForwardRefExoticComponent<IconProps & RefAttributes<SVGSVGElement>>

/** Shape elements an icon may contain. */
type IconElement = "path" | "circle" | "rect" | "ellipse" | "line" | "polyline" | "polygon"

/** An icon's drawing: a flat list of [element, attributes] pairs, lucide compatible. */
type IconNode = ReadonlyArray<readonly [IconElement, Readonly<Record<string, string>>]>

const toPascal = (name: string): string =>
  name
    .split("-")
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join("")

/**
 * Builds a React icon component from an icon node.
 * `name` is the kebab-case icon name, used for the class `chatcn-icon-<name>` and displayName.
 */
function createIcon(name: string, iconNode: IconNode): Icon {
  // biome-ignore lint/correctness/noComponentHookFactories: runs once per icon at module load
  const Component = forwardRef<SVGSVGElement, IconProps>(function ChatcnIcon(
    {
      size = 24,
      strokeWidth = 1.5,
      absoluteStrokeWidth = false,
      color = "currentColor",
      title,
      className,
      children,
      ...rest
    },
    ref,
  ) {
    const stroke = absoluteStrokeWidth
      ? (Number(strokeWidth) * 24) / Number.parseFloat(String(size))
      : strokeWidth
    const labelled = Boolean(title || rest["aria-label"] || rest["aria-labelledby"])
    return createElement(
      "svg",
      {
        ref,
        xmlns: "http://www.w3.org/2000/svg",
        width: size,
        height: size,
        viewBox: "0 0 24 24",
        fill: "none",
        stroke: color,
        strokeWidth: stroke,
        strokeLinecap: "round",
        strokeLinejoin: "round",
        "data-slot": "icon",
        className: className
          ? `chatcn-icon chatcn-icon-${name} ${className}`
          : `chatcn-icon chatcn-icon-${name}`,
        ...(labelled ? { role: "img" } : { "aria-hidden": true }),
        ...rest,
      },
      title ? createElement("title", null, title) : null,
      ...iconNode.map(([tag, attrs], i) => createElement(tag, { key: i, ...attrs })),
      children,
    )
  })
  Component.displayName = `${toPascal(name)}Icon`
  return Component
}

const iconNode: IconNode = [
  ["path", {"d":"m3.5 3.5 17 17"}],
  ["path", {"d":"M6.64 3H18a3 3 0 0 1 3 3v11.36"}],
  ["path", {"d":"M17.36 21H6a3 3 0 0 1-3-3V6.64"}],
