const ImageOffIcon: Icon = /* @__PURE__ */ createIcon("image-off", iconNode)

function ImageOutput({ output }: { output: NotebookImageOutput }) {
  const [state, setState] = React.useState<"loading" | "loaded" | "error">("loading")
  const ref = React.useRef<HTMLImageElement>(null)
  // A cached image can finish before React attaches onLoad.
  React.useEffect(() => {
    const img = ref.current
    if (img?.complete && img.naturalWidth > 0) setState("loaded")
  }, [])

  return (
    <div
      data-slot="notebook-output"
      data-output-type="image"
      className={cn(
        "rounded-(--chatcn-radius-md) relative max-w-full overflow-hidden",
        state !== "loaded" && "bg-(color:--chatcn-fill)",
      )}
      style={{ width: output.width, aspectRatio: `${output.width} / ${output.height}` }}
    >
      {state === "error" ? (
        <div className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) absolute inset-0 flex flex-col items-center justify-center gap-1.5 p-4 text-center">
          <ImageOffIcon aria-hidden="true" className="size-4" />
          <span>The image could not load. Re-run the cell to render it again.</span>
        </div>
      ) : (
        <img
          ref={ref}
          src={output.src}
          alt={output.alt}
          width={output.width}
          height={output.height}
          draggable={false}
          onLoad={() => setState("loaded")}
          onError={() => setState("error")}
          className={cn(
            "ease-(--chatcn-ease-out) block size-full object-contain transition-opacity duration-200",
            state === "loaded" ? "opacity-100" : "opacity-0",
          )}
        />
      )}
      {/* Hairline so a light chart never bleeds into the surface. */}
      <span className="pointer-events-none absolute inset-0 rounded-[inherit] shadow-[inset_0_0_0_1px_var(--chatcn-alpha-400)]" />
    </div>
  )
}

function ErrorOutput({ output }: { output: NotebookErrorOutput }) {
  const traceback = output.traceback?.join("\n") ?? ""
  return (
    // biome-ignore lint/a11y/useSemanticElements: a labelled group of text, not a form fieldset
    <div
      data-slot="notebook-output"
      data-output-type="error"
      role="group"
      aria-label={`${output.ename}: ${output.evalue}`}
      // A neutral well, as in the terminal: the red name line says what failed and the
      // traceback stays readable instead of sitting in a block of color.
      className="bg-(color:--chatcn-inset) rounded-(--chatcn-radius-md) flex flex-col gap-2 px-3 py-2.5"
    >
      <p
        dir="ltr"
        className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg) flex min-w-0 items-baseline gap-2 font-mono [overflow-wrap:anywhere]"
      >
        <span className="text-(color:--chatcn-red) shrink-0 font-medium">{output.ename}:</span>
        <span className="min-w-0">{output.evalue}</span>
      </p>
      {traceback ? (
        <OutputScroll label="Traceback">
          <AnsiText text={traceback} className="text-(color:--chatcn-fg-muted)" />
        </OutputScroll>
      ) : null}
