}

export function NotebookOutputView({ output }: { output: NotebookOutput }) {
  switch (output.type) {
    case "stream":
      return <StreamOutput output={output} />
    case "text":
      return (
        <div data-slot="notebook-output" data-output-type="text">
          <OutputScroll label="Result">
            <AnsiText text={output.text} className="text-(color:--chatcn-fg)" />
          </OutputScroll>
        </div>
      )
    case "table":
      return <TableOutput output={output} />
    case "image":
      return <ImageOutput output={output} />
    case "error":
      return <ErrorOutput output={output} />
    default: {
      // Unknown mime bundles never crash the cell: show them as JSON text.
      const unknown = output as { type?: unknown }
      let text: string
      try {
        text = JSON.stringify(unknown, null, 2)
      } catch {
        text = String(unknown)
      }
      return (
        <div data-slot="notebook-output" data-output-type="unknown" className="flex flex-col gap-1">
          <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle)">
            {`This output type (${String(unknown.type)}) has no viewer. Showing it as text.`}
          </span>
          <AnsiText text={text} className="text-(color:--chatcn-fg-muted)" />
        </div>
      )
    }
  }
}

