export type NotebookCellStatus = "idle" | "queued" | "running" | "done" | "error"

export interface NotebookCellProps extends Omit<React.ComponentProps<"div">, "children"> {
  code: string
  /** Kernel language. Defaults to `python`. */
  language?: string
  /** `idle` has never run. Defaults to `idle`. */
  status?: NotebookCellStatus
  /** The `[3]` counter. Shown as `[*]` while queued or running. */
  executionCount?: number | null
  outputs?: NotebookOutput[]
  /** The agent is still writing the code: highlights as it arrives, shows the caret, hides Run. */
  streaming?: boolean
  /** Epoch ms when the run started. Measured automatically when omitted. */
  startedAt?: number
  /** Run time in ms, shown once the cell finishes. */
  durationMs?: number
  /** Run or re-run. Also bound to Shift Enter while the cell has focus. */
  onRun?: () => void
  /** Stop a queued or running cell, like Interrupt kernel. */
  onInterrupt?: () => void
  codeCollapsed?: boolean
  defaultCodeCollapsed?: boolean
  onCodeCollapsedChange?: (collapsed: boolean) => void
  outputCollapsed?: boolean
  defaultOutputCollapsed?: boolean
  onOutputCollapsedChange?: (collapsed: boolean) => void
  /** Outputs taller than this scroll. Number means px. Default 320. */
  maxOutputHeight?: number | string
  /** Extra header actions, placed before Copy. */
  actions?: React.ReactNode
  /** `plain` drops the card surface, for a cell inside a panel you already have. */
  variant?: "card" | "plain"
}

const NotebookContext = React.createContext(false)

/* -------------------------------------------------------------------------------------------------
 * Helpers
 * -----------------------------------------------------------------------------------------------*/

function useControllable<T>(value: T | undefined, initial: T, onChange?: (v: T) => void) {
  const [inner, setInner] = React.useState(initial)
  const current = value ?? inner
  const set = React.useCallback(
    (next: T) => {
      if (value === undefined) setInner(next)
      onChange?.(next)
    },
    [value, onChange],
  )
  return [current, set] as const
}

interface UseChatcnElapsedOptions {
  /** True while the timed work is happening. */
  running: boolean
  /** Epoch ms when the work started. Measured from the first `running` render when omitted. */
  startedAt?: number
  /** Final duration from the runtime. Wins over the measured one once `running` is false. */
  durationMs?: number
}

interface UseChatcnElapsedResult {
  /** Live elapsed ms while running, the final duration afterwards, `undefined` when unknown. */
  ms: number | undefined
  running: boolean
}

/**
 * Elapsed time for a step, a run or a reasoning block.
 *
 * Ticks once per second, aligned to the start time so the counter turns over exactly at 1 s,
 * 2 s and so on, never at random offsets. A counter that changes faster only adds noise.
 */
function useChatcnElapsed({
  running,
  startedAt,
  durationMs,
}: UseChatcnElapsedOptions): UseChatcnElapsedResult {
  const [autoStart, setAutoStart] = React.useState<number>()
  const [measured, setMeasured] = React.useState<number>()
  // Starts empty and reads the clock after mount: a render must not read it (Next.js prerender).
  const [now, setNow] = React.useState<number | null>(null)
  const start = startedAt ?? autoStart

  // Record our own start when the caller gives none. A new run (running again) starts over.
  React.useEffect(() => {
    if (!running) return
    if (startedAt === undefined) setAutoStart((prev) => prev ?? Date.now())
    setMeasured(undefined)
    setNow(Date.now())
  }, [running, startedAt])

  // Freeze the measured duration when the work stops.
  const wasRunning = React.useRef(running)
  React.useEffect(() => {
    if (wasRunning.current && !running && start !== undefined) {
      setMeasured(Date.now() - start)
      setAutoStart(undefined)
    }
    wasRunning.current = running
  }, [running, start])

  React.useEffect(() => {
    if (!running || start === undefined) return
    let id: number
    const schedule = () => {
      const elapsed = Date.now() - start
      // Next whole-second boundary, plus a few ms so rounding never shows the old second.
      const wait = 1000 - (((elapsed % 1000) + 1000) % 1000) + 8
      id = window.setTimeout(() => {
        setNow(Date.now())
        schedule()
      }, wait)
    }
    schedule()
    return () => window.clearTimeout(id)
  }, [running, start])

  if (running)
    return { ms: start === undefined ? undefined : Math.max(0, (now ?? start) - start), running }
  return { ms: durationMs ?? measured, running }
}

/** Joins consecutive stream chunks of the same name, the way Jupyter prints them. */
function mergeStreams(outputs: NotebookOutput[]) {
  const out: NotebookOutput[] = []
  for (const output of outputs) {
    const last = out.at(-1)
    if (output.type === "stream" && last?.type === "stream" && last.name === output.name) {
      out[out.length - 1] = { ...last, text: last.text + output.text }
    } else out.push(output)
  }
  return out
}

