/** Copy swaps to a check with a 150 ms blur crossfade, holds for 1.5 s and announces itself. */
function CopyButton({
  value,
  label = "Copy",
  onCopy,
  onClick,
  children,
  size = "icon-sm",
  className,
  ...props
}: CopyButtonProps) {
  // A counter, not a flag: copying again while the check shows restarts the 1.5 s hold.
  const [copies, setCopies] = React.useState(0)
  const [copied, setCopied] = React.useState(false)
  React.useEffect(() => {
    if (!copies) return
    setCopied(true)
    const id = window.setTimeout(() => setCopied(false), 1500)
    return () => window.clearTimeout(id)
  }, [copies])

  // Reduced motion keeps the crossfade and drops the scale and blur.
  const layer = cn(
    "ease-(--chatcn-ease-out) absolute transition-[opacity,scale,filter] duration-150",
    "motion-reduce:scale-100 motion-reduce:blur-none motion-reduce:transition-opacity",
  )
  return (
    <Button
      {...props}
      size={size}
      aria-label={children ? undefined : copied ? "Copied" : label}
      onClick={(event) => {
        // Compose with handlers injected by wrappers such as Tooltip instead of replacing them.
        onClick?.(event)
        if (event.defaultPrevented) return
        const text = typeof value === "function" ? value() : value
        navigator.clipboard
          ?.writeText(text)
          .then(() => {
            setCopies((n) => n + 1)
            onCopy?.(text)
          })
          // Clipboard access can be denied (insecure context, permissions). Stay quiet and unchanged.
          .catch(() => {})
      }}
      className={cn("relative", className)}
    >
      {children ? (
        <>
          <span className="relative grid size-3.5 place-items-center">
            <CopyIcon
              className={cn(
                layer,
                copied ? "scale-75 opacity-0 blur-[2px]" : "scale-100 opacity-100",
              )}
            />
            <CheckIcon
              className={cn(
                layer,
                copied ? "scale-100 opacity-100" : "scale-75 opacity-0 blur-[2px]",
              )}
            />
          </span>
          {children}
        </>
      ) : null}
      {children ? null : (
        <>
          <CopyIcon
            className={cn(
              layer,
              copied ? "scale-75 opacity-0 blur-[2px]" : "scale-100 opacity-100",
            )}
          />
          <CheckIcon
            className={cn(
              layer,
              copied ? "scale-100 opacity-100" : "scale-75 opacity-0 blur-[2px]",
            )}
          />
        </>
      )}
      <span aria-live="polite" className="sr-only">
        {copied ? "Copied" : ""}
      </span>
    </Button>
  )
}

/* -------------------------------------------------------------------------------------------------
 * Roles and theme
 * -----------------------------------------------------------------------------------------------*/

type ChatcnTokenRole =
  | "plain"
  | "keyword"
  | "comment"
  | "string"
  | "constant"
  | "function"
  | "type"
  | "tag"
  | "attribute"
  | "punctuation"

interface ChatcnToken {
  content: string
  role: ChatcnTokenRole
}

type ChatcnTokenLine = ChatcnToken[]

/** Return value of `useChatcnHighlight`. */
interface UseChatcnHighlightResult {
  lines: ChatcnTokenLine[]
  /** False while the grammar loads (lines are plain) or for unknown languages. */
  highlighted: boolean
}

const PLAIN = new Set(["text", "txt", "plain", "plaintext", "ansi", "log", "output"])

let ready: HighlighterCore | undefined

const loaded = new Set<string>()

/** True once `lang` can be tokenized synchronously. */
function isLanguageReady(lang?: string | null) {
  const id = resolveLanguage(lang)
  return PLAIN.has(id) || (ready !== undefined && loaded.has(id))
}

const missing = new Set<string>()

const pending = new Map<string, Promise<boolean>>()

/* -------------------------------------------------------------------------------------------------
 * Loading
 * -----------------------------------------------------------------------------------------------*/

let core: Promise<HighlighterCore> | undefined

// Shiki needs a color per scope. The "color" is the role name, read back in `toLine`.
const role = (name: ChatcnTokenRole) => `var(--chatcn-code-${name})`

const chatcnTheme: ThemeRegistration = {
  name: "chatcn",
  type: "light",
  colors: { "editor.foreground": role("plain"), "editor.background": "transparent" },
  tokenColors: [
    {
