const ChevronDownIcon: Icon = /* @__PURE__ */ createIcon("chevron-down", iconNode13)

function outputSummary(outputs: NotebookOutput[]) {
  if (outputs.some((o) => o.type === "error")) return "Error"
  const kinds = new Set(outputs.map((o) => o.type))
  if (kinds.size === 1) {
    if (kinds.has("image")) return outputs.length === 1 ? "1 image" : `${outputs.length} images`
    if (kinds.has("table")) return outputs.length === 1 ? "1 table" : `${outputs.length} tables`
  }
  const lines = outputs
    .filter((o): o is NotebookStreamOutput | NotebookTextOutput => "text" in o)
    .reduce((n, o) => n + o.text.replace(/\n$/, "").split("\n").length, 0)
  const rest = outputs.filter((o) => o.type !== "stream" && o.type !== "text").length
  const parts = []
  if (lines) parts.push(`${lines} ${lines === 1 ? "line" : "lines"}`)
  if (rest) parts.push(`${rest} more ${rest === 1 ? "item" : "items"}`)
  return parts.join(", ")
}

/* -------------------------------------------------------------------------------------------------
 * NotebookCell
 * -----------------------------------------------------------------------------------------------*/

/**
 * One cell a data agent ran: execution count, highlighted code, status with a live timer, and
 * nbformat-style outputs (streams, results, DataFrames, charts and tracebacks). Code and output
 * collapse independently. Shift Enter runs the focused cell.
 */
export function NotebookCell({
  code,
  language = "python",
  status = "idle",
  executionCount,
  outputs = [],
  streaming = false,
  startedAt,
  durationMs,
  onRun,
  onInterrupt,
  codeCollapsed: codeCollapsedProp,
  defaultCodeCollapsed = false,
  onCodeCollapsedChange,
  outputCollapsed: outputCollapsedProp,
  defaultOutputCollapsed = false,
  onOutputCollapsedChange,
  maxOutputHeight = 320,
  actions,
  variant = "card",
  className,
  onKeyDown,
  ...props
}: NotebookCellProps) {
  const inNotebook = React.useContext(NotebookContext)
  const id = React.useId()
  const [codeCollapsed, setCodeCollapsed] = useControllable(
    codeCollapsedProp,
    defaultCodeCollapsed,
    onCodeCollapsedChange,
  )
  const [outputCollapsed, setOutputCollapsed] = useControllable(
    outputCollapsedProp,
    defaultOutputCollapsed,
    onOutputCollapsedChange,
  )

  const running = status === "running"
  const busy = running || status === "queued"
  const elapsed = useChatcnElapsed({ running, startedAt, durationMs })
  const merged = React.useMemo(() => mergeStreams(outputs), [outputs])
  const hasOutputs = merged.length > 0
  const error = merged.find((o): o is NotebookErrorOutput => o.type === "error")
  const label = languageLabel(language)
  const count = countLabel(status, executionCount)

  const outputContext = React.useMemo(
    () => ({ maxHeight: maxOutputHeight, running }),
    [maxOutputHeight, running],
  )

  let meta: React.ReactNode = null
  if (streaming) meta = <ShimmerText>Writing</ShimmerText>
  else if (status === "queued") meta = "Queued"
  else if (running)
    meta =
      elapsed.ms !== undefined && elapsed.ms >= 1000 ? (
        <span dir="ltr">{formatChatcnDuration(elapsed.ms, { precise: false })}</span>
      ) : (
        <ShimmerText>Running</ShimmerText>
      )
  else if (status === "done" || status === "error") {
    const time =
      elapsed.ms !== undefined ? <span dir="ltr">{formatChatcnDuration(elapsed.ms)}</span> : null
    meta =
      status === "error" ? (
        <>
          <span className="text-(color:--chatcn-red)">Failed</span>
          {time}
        </>
      ) : (
        (time ?? "Done")
      )
  } else meta = "Not run"

  const announcement =
    status === "done"
      ? `${countName(status, executionCount)} finished${
          elapsed.ms !== undefined ? ` in ${formatChatcnDuration(elapsed.ms)}` : ""
        }`
      : status === "error"
        ? `${countName(status, executionCount)} failed${error ? `: ${error.ename}` : ""}`
        : ""

  const runButton = streaming ? null : busy ? (
    onInterrupt ? (
      <Tooltip content={running ? "Interrupt" : "Remove from queue"}>
        <Button
          size="icon-sm"
          aria-label={running ? "Interrupt cell" : "Remove from queue"}
          onClick={onInterrupt}
        >
          <CircleStopIcon />
        </Button>
      </Tooltip>
    ) : null
  ) : onRun ? (
    <Tooltip content={status === "idle" ? "Run cell" : "Re-run cell"} shortcut="Shift Enter">
      <Button
        size="icon-sm"
        aria-label={status === "idle" ? "Run cell" : "Re-run cell"}
        onClick={onRun}
      >
        {status === "idle" ? <PlayIcon /> : <RotateCcwIcon />}
      </Button>
    </Tooltip>
  ) : null

  const showOutputRegion = hasOutputs || running

  return (
    // biome-ignore lint/a11y/useSemanticElements: a labelled group of text, not a form fieldset
    <div
      role="group"
      aria-label={`${countName(status, executionCount)}, ${label}`}
      aria-busy={busy || streaming || undefined}
      data-slot="notebook-cell"
      data-notebook-cell-state={status}
      data-variant={variant}
      onKeyDown={(event) => {
        onKeyDown?.(event)
        if (event.defaultPrevented) return
        const target = event.target as HTMLElement
        if (
          event.key === "Enter" &&
          event.shiftKey &&
          !event.nativeEvent.isComposing &&
          target.tagName !== "BUTTON" &&
          onRun &&
          !busy &&
          !streaming
        ) {
          event.preventDefault()
          onRun()
        }
      }}
      className={cn(
        "group/notebook-cell text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg) min-w-0",
        inNotebook && "grid grid-cols-[3rem_minmax(0,1fr)] gap-x-2",
        className,
      )}
      {...props}
    >
      {inNotebook ? (
        <span
          aria-hidden="true"
          className={cn(
            "text-[0.75rem]/[1rem] h-10 text-end font-mono leading-10 tabular-nums select-none",
            busy ? "text-(color:--chatcn-blue)" : "text-(color:--chatcn-fg-subtle)",
          )}
        >
          {count}
        </span>
      ) : null}

      <div
        className={cn(
          "min-w-0",
          variant === "card" &&
            "rounded-(--chatcn-radius-lg) bg-(color:--chatcn-card) shadow-(--chatcn-shadow-sm) overflow-hidden forced-colors:outline-1 forced-colors:outline-solid",
        )}
      >
        <div
          data-slot="notebook-cell-header"
          className="flex h-10 min-w-0 items-center gap-2.5 ps-3.5 pe-1.5 pointer-coarse:h-11"
        >
          <NotebookCellGlyph status={status} />
          <span className="flex min-w-0 flex-1 items-baseline gap-2">
            {inNotebook ? null : (
              <span
                aria-hidden="true"
                className={cn(
                  "text-[0.75rem]/[1rem] shrink-0 font-mono tabular-nums",
                  busy ? "text-(color:--chatcn-blue)" : "text-(color:--chatcn-fg-subtle)",
                )}
              >
                {count}
              </span>
            )}
            <span className="truncate font-medium">{label}</span>
          </span>
          <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) flex shrink-0 items-center gap-1.5 tabular-nums">
            {meta}
          </span>
          <div className="flex shrink-0 items-center gap-0.5">
            {actions}
            <Tooltip content={codeCollapsed ? "Show code" : "Collapse code"}>
              <Button
                size="icon-sm"
                aria-label={codeCollapsed ? "Show code" : "Collapse code"}
                aria-expanded={!codeCollapsed}
                aria-controls={`${id}-code`}
                onClick={() => setCodeCollapsed(!codeCollapsed)}
              >
                {codeCollapsed ? <ChevronsUpDownIcon /> : <ChevronsDownUpIcon />}
              </Button>
            </Tooltip>
            {streaming ? null : <CopyButton value={code.replace(/\n$/, "")} label="Copy code" />}
            {runButton}
          </div>
        </div>

        <NotebookCellCode
          id={`${id}-code`}
          code={code}
          language={language}
          streaming={streaming}
          collapsed={codeCollapsed}
          onExpand={() => setCodeCollapsed(false)}
        />

        {showOutputRegion ? (
          <Collapsible.Root
            open={!outputCollapsed}
            onOpenChange={(open) => setOutputCollapsed(!open)}
            render={<div />}
            data-slot="notebook-cell-outputs"
            className="border-(color:--chatcn-border) group/outputs border-t"
          >
            <Collapsible.Trigger
              className={cn(
                "text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) hover:text-(color:--chatcn-fg) flex h-8 w-full items-center gap-1.5 ps-3.5 pe-3 text-start outline-none select-none pointer-coarse:h-11",
                "ease-(--chatcn-ease-standard) transition-colors duration-150",
                "focus-visible:outline-(color:--chatcn-accent) focus-visible:outline-2 focus-visible:-outline-offset-2",
              )}
            >
              <ChevronDownIcon
                aria-hidden="true"
                className={cn(
                  "ease-(--chatcn-ease-out) size-3.5 shrink-0 -rotate-90 transition-transform duration-150 motion-reduce:transition-none rtl:rotate-90",
                  "group-data-[open]/outputs:rotate-0",
                )}
              />
              <span className="font-medium">{error ? "Error" : "Output"}</span>
              {outputCollapsed && hasOutputs ? (
                <span className="truncate tabular-nums">{outputSummary(merged)}</span>
              ) : null}
            </Collapsible.Trigger>
            <Collapsible.Panel
              className={cn(
                "h-(--collapsible-panel-height) overflow-hidden",
                "ease-(--chatcn-ease-out) transition-[height,opacity] duration-200 motion-reduce:transition-none",
                "data-[ending-style]:h-0 data-[ending-style]:opacity-0 data-[starting-style]:h-0 data-[starting-style]:opacity-0",
              )}
            >
              <OutputContext.Provider value={outputContext}>
                <div className="flex flex-col gap-3 px-3.5 pt-0.5 pb-3.5">
                  {hasOutputs ? (
                    merged.map((output, i) => <NotebookOutputView key={i} output={output} />)
                  ) : (
                    <p className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) min-h-5 leading-5">
                      Waiting for output…
                    </p>
                  )}
                </div>
              </OutputContext.Provider>
            </Collapsible.Panel>
          </Collapsible.Root>
        ) : status === "done" ? (
          <p className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) border-(color:--chatcn-border) border-t px-3.5 py-2">
            No output
          </p>
        ) : null}
      </div>

      <span aria-live="polite" className="sr-only">
        {announcement}
      </span>
    </div>
  )
}

/* -------------------------------------------------------------------------------------------------
 * Notebook: cells stacked with their counters in one aligned gutter.
 * -----------------------------------------------------------------------------------------------*/

export interface NotebookProps extends Omit<React.ComponentProps<"div">, "title"> {
  /** File name, for example `churn-march-2026.ipynb`. */
  title?: React.ReactNode
  /** Kernel line, for example `Python 3.12`. */
  kernel?: React.ReactNode
  /** Kernel state shown next to the kernel name. */
  kernelStatus?: "idle" | "busy" | "disconnected"
  /** Header actions, such as Run all. */
  actions?: React.ReactNode
}

export function Notebook({
  title,
  kernel,
  kernelStatus = "idle",
  actions,
  className,
  children,
  ...props
}: NotebookProps) {
  const hasHeader = title !== undefined || kernel !== undefined || actions !== undefined
  return (
    <NotebookContext.Provider value={true}>
      <div
        data-slot="notebook"
        data-kernel-state={kernelStatus}
        className={cn("flex min-w-0 flex-col gap-3", className)}
        {...props}
      >
        {hasHeader ? (
          <div className="flex min-h-9 min-w-0 items-center gap-3 ps-14">
            {title !== undefined ? (
              <h3 className="text-[0.875rem]/[1.25rem] tracking-[-0.003em] min-w-0 truncate font-mono font-medium">{title}</h3>
            ) : null}
            {kernel !== undefined ? (
              <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) flex shrink-0 items-center gap-1.5">
                <span
                  aria-hidden="true"
                  className={cn(
                    "size-1.5 rounded-full",
                    kernelStatus === "busy"
                      ? "bg-(color:--chatcn-blue)"
                      : kernelStatus === "disconnected"
                        ? "bg-(color:--chatcn-red)"
                        : "bg-(color:--chatcn-green)",
                  )}
                />
                {kernel}
                <span>
                  {kernelStatus === "busy"
                    ? "Busy"
                    : kernelStatus === "disconnected"
                      ? "Disconnected"
                      : "Idle"}
                </span>
              </span>
            ) : null}
            <span className="flex-1" />
            {actions ? <div className="flex shrink-0 items-center gap-1">{actions}</div> : null}
          </div>
        ) : null}
        {children}
      </div>
    </NotebookContext.Provider>
  )
}

