          : window.setTimeout(() => setPhase("queued"), 400)
    } else if (phase === "queued") {
      id = window.setTimeout(() => {
        setStartedAt(Date.now())
        setPhase("running")
      }, 900)
    } else if (phase === "running") {
      id =
        printed < LINES.length
          ? window.setTimeout(() => setPrinted((n) => n + 1), 900)
          : window.setTimeout(() => {
              setTable(true)
              setPhase("done")
            }, 700)
    } else {
      id = window.setTimeout(() => {
        setLength(0)
        setPrinted(0)
        setTable(false)
        setCount((n) => n + 1)
        setPhase("writing")
      }, 5000)
    }
    return () => window.clearTimeout(id)
  }, [phase, length, printed])

  const outputs: NotebookOutput[] = [
    ...(printed > 0
      ? [
          {
            type: "stream" as const,
            name: "stdout" as const,
            text: LINES.slice(0, printed).join(""),
          },
        ]
      : []),
    ...(table ? byPlanOutputs : []),
  ]

  return (
    <NotebookCell
      className="w-full max-w-2xl"
      code={CODE.slice(0, length)}
      streaming={phase === "writing"}
      status={phase === "writing" ? "idle" : phase}
      executionCount={phase === "done" ? count : null}
      startedAt={startedAt}
      outputs={outputs}
      onRun={() => {
        setPrinted(0)
        setTable(false)
        setCount((n) => n + 1)
        setPhase("queued")
      }}
      onInterrupt={() => setPhase("done")}
    />
  )
}

